SELECT "line_id", "request_number", "item", "quantity", "way", "customer", "obligation_id", "due", "obligation_state", "qty_ok", "qty_bad", "last_received", "days_open", "reminders", "route", 'incomplete or damaged return' AS "verdict_reason"
FROM (SELECT "t22"."line_id", "t22"."request_number", "t22"."item", "t22"."quantity", "t22"."way", "t22"."customer", "t22"."obligation_id", "t22"."due", "t22"."obligation_state", "t22"."qty_ok", "t22"."qty_bad", "t22"."last_received", "t22"."days_open", "t26"."reminders", CASE WHEN "t22"."qty_ok" >= "t22"."quantity" THEN 'complete' WHEN "t22"."qty_bad" > 0 OR "t22"."qty_ok" > 0 AND "t22"."qty_ok" < "t22"."quantity" THEN 'damaged' WHEN "t22"."days_open" > :inbound_close THEN 'expired' WHEN "t22"."days_open" > :inbound_reminder AND "t26"."reminders" = 0 THEN 'remind' ELSE NULL END AS "route"
        FROM (SELECT "t8"."line_id", "t8"."request_number", "t8"."item", "t8"."quantity", "t8"."way", "t8"."customer", "t8"."obligation_id", "t8"."due", "t8"."obligation_state", "t8"."qty_ok", "t8"."qty_bad", "t8"."last_received", "t21"."days_open"
                FROM (SELECT "t1"."line_id", "t1"."request_number", "t1"."item", "t1"."quantity", "t1"."way", "t1"."customer", "t1"."obligation_id", "t1"."due", "t1"."obligation_state", "t7"."qty_ok", "t7"."qty_bad", "t7"."last_received"
                        FROM (SELECT "t"."line_id", "t"."request_number", "t"."item", "t"."quantity", "t"."way", "t"."customer0" AS "customer", "obligation"."id" AS "obligation_id", "obligation"."due", "obligation"."state" AS "obligation_state"
                                FROM (SELECT "return_request_line"."line_id", "return_request_line"."request_number", "return_request_line"."line_no", "return_request_line"."item", "return_request_line"."quantity", "return_request_line"."unit_price", "return_request_line"."reason", "return_request_line"."requested_resolution", "return_request_line"."requested_variant", "return_request_line"."state", "return_request_line"."way", "return_request_line"."customer", "return_request"."customer" AS "customer0", "return_request"."order_number", "return_request"."channel", "return_request"."requested_date", "return_request"."state" AS "state0"
                                        FROM "return_request_line"
                                            INNER JOIN "return_request" ON "return_request_line"."request_number" = "return_request"."request_number") AS "t"
                                    INNER JOIN "obligation" ON "obligation"."entity" = 'return_request_line' AND "obligation"."key" = CAST("t"."line_id" AS VARCHAR) AND "obligation"."kind" = 'inbound' AND "obligation"."state" IN ('open', 'overdue', 'reopened')
                                WHERE "t"."state" = 'awaiting_goods') AS "t1"
                            LEFT JOIN (SELECT "t4"."line_id", COALESCE(SUM(CASE WHEN "return_receipt"."condition" = 'ok' THEN "return_receipt"."quantity" ELSE 0 END), 0) AS "qty_ok", COALESCE(SUM(CASE WHEN "return_receipt"."condition" <> 'ok' THEN "return_receipt"."quantity" ELSE 0 END), 0) AS "qty_bad", MAX("return_receipt"."received_date") AS "last_received"
                                FROM (SELECT "t2"."line_id", "t2"."request_number", "t2"."item", "t2"."quantity", "t2"."way", "t2"."customer0" AS "customer", "obligation0"."id" AS "obligation_id", "obligation0"."due", "obligation0"."state" AS "obligation_state"
                                        FROM (SELECT "return_request_line0"."line_id", "return_request_line0"."request_number", "return_request_line0"."line_no", "return_request_line0"."item", "return_request_line0"."quantity", "return_request_line0"."unit_price", "return_request_line0"."reason", "return_request_line0"."requested_resolution", "return_request_line0"."requested_variant", "return_request_line0"."state", "return_request_line0"."way", "return_request_line0"."customer", "return_request0"."customer" AS "customer0", "return_request0"."order_number", "return_request0"."channel", "return_request0"."requested_date", "return_request0"."state" AS "state0"
                                                FROM "return_request_line" AS "return_request_line0"
                                                    INNER JOIN "return_request" AS "return_request0" ON "return_request_line0"."request_number" = "return_request0"."request_number") AS "t2"
                                            INNER JOIN "obligation" AS "obligation0" ON "obligation0"."entity" = 'return_request_line' AND "obligation0"."key" = CAST("t2"."line_id" AS VARCHAR) AND "obligation0"."kind" = 'inbound' AND "obligation0"."state" IN ('open', 'overdue', 'reopened')
                                        WHERE "t2"."state" = 'awaiting_goods') AS "t4"
                                    LEFT JOIN "return_receipt" ON "t4"."line_id" = "return_receipt"."line_id"
                                GROUP BY "t4"."line_id") AS "t7" ON "t1"."line_id" = "t7"."line_id") AS "t8"
                    LEFT JOIN (SELECT "t12"."line_id", CASE WHEN "t12"."created_at" IS NULL THEN NULL ELSE COALESCE("t20"."_ttrp_n_n15_0", 0) END AS "days_open"
                        FROM (SELECT "t11"."line_id", "t11"."request_number", "t11"."item", "t11"."quantity", "t11"."way", "t11"."customer", "t11"."obligation_id", "t11"."due", "t11"."obligation_state", "obligation2"."recipe", "obligation2"."run", "obligation2"."entity", "obligation2"."key", "obligation2"."kind", "obligation2"."due" AS "due0", "obligation2"."state", "obligation2"."fulfilled_by", "obligation2"."fulfilled_at", "obligation2"."created_at"
                                FROM (SELECT "t9"."line_id", "t9"."request_number", "t9"."item", "t9"."quantity", "t9"."way", "t9"."customer0" AS "customer", "obligation1"."id" AS "obligation_id", "obligation1"."due", "obligation1"."state" AS "obligation_state"
                                        FROM (SELECT "return_request_line1"."line_id", "return_request_line1"."request_number", "return_request_line1"."line_no", "return_request_line1"."item", "return_request_line1"."quantity", "return_request_line1"."unit_price", "return_request_line1"."reason", "return_request_line1"."requested_resolution", "return_request_line1"."requested_variant", "return_request_line1"."state", "return_request_line1"."way", "return_request_line1"."customer", "return_request1"."customer" AS "customer0", "return_request1"."order_number", "return_request1"."channel", "return_request1"."requested_date", "return_request1"."state" AS "state0"
                                                FROM "return_request_line" AS "return_request_line1"
                                                    INNER JOIN "return_request" AS "return_request1" ON "return_request_line1"."request_number" = "return_request1"."request_number") AS "t9"
                                            INNER JOIN "obligation" AS "obligation1" ON "obligation1"."entity" = 'return_request_line' AND "obligation1"."key" = CAST("t9"."line_id" AS VARCHAR) AND "obligation1"."kind" = 'inbound' AND "obligation1"."state" IN ('open', 'overdue', 'reopened')
                                        WHERE "t9"."state" = 'awaiting_goods') AS "t11"
                                    INNER JOIN "obligation" AS "obligation2" ON "t11"."obligation_id" = "obligation2"."id") AS "t12"
                            LEFT JOIN (SELECT "t17"."created_at" AS "_ttrp_k_n15_0_created_at", COUNT("t18"."_ttrp_d_n15_0") AS "_ttrp_n_n15_0"
                                FROM (SELECT "obligation4"."created_at"
                                        FROM (SELECT "t13"."line_id", "t13"."request_number", "t13"."item", "t13"."quantity", "t13"."way", "t13"."customer0" AS "customer", "obligation3"."id" AS "obligation_id", "obligation3"."due", "obligation3"."state" AS "obligation_state"
                                                FROM (SELECT "return_request_line2"."line_id", "return_request_line2"."request_number", "return_request_line2"."line_no", "return_request_line2"."item", "return_request_line2"."quantity", "return_request_line2"."unit_price", "return_request_line2"."reason", "return_request_line2"."requested_resolution", "return_request_line2"."requested_variant", "return_request_line2"."state", "return_request_line2"."way", "return_request_line2"."customer", "return_request2"."customer" AS "customer0", "return_request2"."order_number", "return_request2"."channel", "return_request2"."requested_date", "return_request2"."state" AS "state0"
                                                        FROM "return_request_line" AS "return_request_line2"
                                                            INNER JOIN "return_request" AS "return_request2" ON "return_request_line2"."request_number" = "return_request2"."request_number") AS "t13"
                                                    INNER JOIN "obligation" AS "obligation3" ON "obligation3"."entity" = 'return_request_line' AND "obligation3"."key" = CAST("t13"."line_id" AS VARCHAR) AND "obligation3"."kind" = 'inbound' AND "obligation3"."state" IN ('open', 'overdue', 'reopened')
                                                WHERE "t13"."state" = 'awaiting_goods') AS "t15"
                                            INNER JOIN "obligation" AS "obligation4" ON "t15"."obligation_id" = "obligation4"."id"
                                        GROUP BY "obligation4"."created_at") AS "t17"
                                    INNER JOIN (SELECT "cal_date" AS "_ttrp_d_n15_0"
                                        FROM "date_dim") AS "t18" ON "t17"."created_at" < "t18"."_ttrp_d_n15_0" AND "t18"."_ttrp_d_n15_0" <= :as_of
                                GROUP BY "t17"."created_at") AS "t20" ON "t12"."created_at" = "t20"."_ttrp_k_n15_0_created_at") AS "t21" ON "t8"."line_id" = "t21"."line_id") AS "t22"
            LEFT JOIN (SELECT "t25"."line_id", COUNT("monitor_inbound_verdict"."run") AS "reminders"
                FROM (SELECT "t23"."line_id", "t23"."request_number", "t23"."item", "t23"."quantity", "t23"."way", "t23"."customer0" AS "customer", "obligation5"."id" AS "obligation_id", "obligation5"."due", "obligation5"."state" AS "obligation_state"
                        FROM (SELECT "return_request_line3"."line_id", "return_request_line3"."request_number", "return_request_line3"."line_no", "return_request_line3"."item", "return_request_line3"."quantity", "return_request_line3"."unit_price", "return_request_line3"."reason", "return_request_line3"."requested_resolution", "return_request_line3"."requested_variant", "return_request_line3"."state", "return_request_line3"."way", "return_request_line3"."customer", "return_request3"."customer" AS "customer0", "return_request3"."order_number", "return_request3"."channel", "return_request3"."requested_date", "return_request3"."state" AS "state0"
                                FROM "return_request_line" AS "return_request_line3"
                                    INNER JOIN "return_request" AS "return_request3" ON "return_request_line3"."request_number" = "return_request3"."request_number") AS "t23"
                            INNER JOIN "obligation" AS "obligation5" ON "obligation5"."entity" = 'return_request_line' AND "obligation5"."key" = CAST("t23"."line_id" AS VARCHAR) AND "obligation5"."kind" = 'inbound' AND "obligation5"."state" IN ('open', 'overdue', 'reopened')
                        WHERE "t23"."state" = 'awaiting_goods') AS "t25"
                    LEFT JOIN "monitor_inbound_verdict" ON "t25"."line_id" = "monitor_inbound_verdict"."line_id" AND "monitor_inbound_verdict"."route" = 'remind'
                GROUP BY "t25"."line_id") AS "t26" ON "t22"."line_id" = "t26"."line_id") AS "t27"
WHERE "t27"."route" = 'damaged'
